-- SobriZen: one server consent boundary for private tracking and journal data.
-- Prepared from the production schema/policies read on 2026-11-09. No user data
-- is changed by this migration. Apply before deploying the matching app modules.
-- Versioned migrations are generated by Supabase CLI v3 for this release.
-- References (consulted 2026-11-09):
-- https://supabase.com/docs/guides/database/postgres/row-level-security
-- https://supabase.com/docs/guides/database/functions#security-definer-vs-invoker
-- https://supabase.com/docs/guides/storage/security/access-control
-- https://supabase.com/docs/guides/api/securing-your-api
begin;

-- Private-schema helper: no user argument, current authenticated identity only.
-- Invoker is sufficient because it reads only the owner's public consent columns.
create or replace function private.sobrizen_health_consent_active()
returns boolean language sql stable security invoker set search_path = ''
as $$
  select auth.uid() is not null and exists (
    select 1 from public.user_settings s
    where s.user_id = (select auth.uid())
      and s.health_data_consent_at is not null
      and s.health_data_consent_revoked_at is null
  );
$$;
revoke all on function private.sobrizen_health_consent_active() from public, anon;
grant usage on schema private to authenticated;
grant execute on function private.sobrizen_health_consent_active() to authenticated;

-- Restrictive policies are ANDed with existing owner policies; they cannot
-- accidentally widen ownership or remove an additional domain constraint.
-- Health already has a consent guard; the extra boundary makes the rule uniform.
do $$
declare target text;
begin
  foreach target in array array[
    'sobriety_journeys','daily_checkins','journal_entries','program_progress',
    'urge_events','reasons','health_checkins','journey_timelines',
    'progress_settings','progress_chapters'
  ] loop
    execute format('create policy sensitive_consent_read on public.%I as restrictive for select to authenticated using ((select private.sobrizen_health_consent_active()))',target);
    execute format('create policy sensitive_consent_insert on public.%I as restrictive for insert to authenticated with check ((select private.sobrizen_health_consent_active()))',target);
    execute format('create policy sensitive_consent_update on public.%I as restrictive for update to authenticated using ((select private.sobrizen_health_consent_active())) with check ((select private.sobrizen_health_consent_active()))',target);
  end loop;
end;
$$;

-- No change to profile, community, billing requests, account deletion requests,
-- agenda or game records. Existing owner DELETE policies remain in place.
-- Read access without consent for a requested export is a separate RPC below.
-- Auth bootstrap/service roles are not subject to authenticated RLS policies.

-- Private journal pictures use the same normal-read/write boundary. Community
-- images and avatars retain their current policies. Cleanup/delete is not given
-- new consent requirements. Previously downloaded bytes cannot be recalled.
create policy journal_images_consent_read on storage.objects as restrictive
for select to authenticated using (
  bucket_id <> 'journal-images' or (select private.sobrizen_health_consent_active())
);
create policy journal_images_consent_upload on storage.objects as restrictive
for insert to authenticated with check (
  bucket_id <> 'journal-images' or (select private.sobrizen_health_consent_active())
);

-- user_settings mixes safe account controls and four sensitive plan columns.
-- Keep consent/reminders/community controls readable and writable without
-- consent. Full private settings are exposed only by the checked RPCs below.
revoke select on public.user_settings from public, anon, authenticated;
revoke select (support_name,support_phone,risky_situation,response_plan)
  on public.user_settings from public, anon, authenticated;
grant select (user_id,privacy_ack_at,health_data_consent_at,
  health_data_consent_version,health_data_consent_revoked_at,hidden_authors,
  reminder_time,updated_at) on public.user_settings to authenticated;

create or replace function private.guard_private_settings_write()
returns trigger language plpgsql security invoker set search_path = ''
as $$
declare changed boolean;
begin
  if tg_op = 'INSERT' then
    changed := new.support_name is not null or new.support_phone is not null
      or new.risky_situation is not null or new.response_plan is not null;
  else
    changed := row(new.support_name,new.support_phone,new.risky_situation,new.response_plan)
      is distinct from row(old.support_name,old.support_phone,old.risky_situation,old.response_plan);
  end if;
  -- For actual authenticated client requests (including checked definer RPCs).
  -- Maintenance/auth-bootstrap without an end-user JWT remains possible.
  if auth.uid() is not null and changed and (
    new.user_id <> auth.uid() or new.health_data_consent_at is null
    or new.health_data_consent_revoked_at is not null
  ) then
    raise exception using errcode='42501',message='Active le consentement au suivi pour modifier ton plan personnel.';
  end if;
  return new;
end;
$$;
revoke all on function private.guard_private_settings_write() from public, anon, authenticated;
create or replace trigger user_settings_private_consent before insert or update on public.user_settings
for each row execute function private.guard_private_settings_write();

create or replace function public.read_private_settings()
returns jsonb language plpgsql stable security definer set search_path = ''
as $$
declare uid uuid := auth.uid(); result jsonb;
begin
  if uid is null then raise exception using errcode='42501',message='Connecte-toi pour ouvrir ton suivi.'; end if;
  select to_jsonb(s) into result from public.user_settings s where s.user_id=uid
    and s.health_data_consent_at is not null and s.health_data_consent_revoked_at is null;
  if result is null then raise exception using errcode='42501',message='Active le consentement au suivi pour ouvrir ton plan personnel.'; end if;
  return result;
end;
$$;
revoke all on function public.read_private_settings() from public, anon;
grant execute on function public.read_private_settings() to authenticated;

create or replace function public.save_private_settings(p_settings jsonb)
returns jsonb language plpgsql security definer set search_path = ''
as $$
declare uid uuid := auth.uid(); saved public.user_settings%rowtype; k text; max_length integer;
begin
  if uid is null then raise exception using errcode='42501',message='Connecte-toi pour enregistrer ton plan.'; end if;
  if p_settings is null or jsonb_typeof(p_settings)<>'object' then
    raise exception using errcode='22023',message='Plan personnel invalide.';
  end if;
  for k in select jsonb_object_keys(p_settings) loop
    if k not in ('support_name','support_phone','risky_situation','response_plan','reminder_time') then
      raise exception using errcode='22023',message='Champ de plan personnel non autorisé.';
    end if;
    if jsonb_typeof(p_settings->k) not in ('string','null') then
      raise exception using errcode='22023',message='Un champ du plan personnel est invalide.';
    end if;
    max_length := case k when 'support_name' then 80 when 'support_phone' then 30
      when 'risky_situation' then 1000 when 'response_plan' then 1500 else 8 end;
    if char_length(p_settings->>k)>max_length then
      raise exception using errcode='22023',message='Un champ du plan personnel est trop long.';
    end if;
  end loop;
  if nullif(btrim(p_settings->>'support_phone'),'') is not null
    and (p_settings->>'support_phone') !~ '^\+?[0-9\s().-]{5,30}$' then
    raise exception using errcode='22023',message='Le numéro de la personne de confiance est invalide.';
  end if;
  if p_settings ? 'reminder_time' and (
    p_settings->>'reminder_time' is null or
    (p_settings->>'reminder_time') !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$'
  ) then raise exception using errcode='22023',message='Choisis une heure de rappel valide.'; end if;
  -- Serialize with grant/withdraw updates to the same owner settings row.
  select * into saved from public.user_settings s where s.user_id=uid for update;
  if not found or saved.health_data_consent_at is null or saved.health_data_consent_revoked_at is not null then
    raise exception using errcode='42501',message='Active le consentement au suivi pour enregistrer ton plan personnel.';
  end if;
  update public.user_settings s set
    support_name=case when p_settings?'support_name' then nullif(btrim(p_settings->>'support_name'),'') else s.support_name end,
    support_phone=case when p_settings?'support_phone' then nullif(btrim(p_settings->>'support_phone'),'') else s.support_phone end,
    risky_situation=case when p_settings?'risky_situation' then nullif(btrim(p_settings->>'risky_situation'),'') else s.risky_situation end,
    response_plan=case when p_settings?'response_plan' then nullif(btrim(p_settings->>'response_plan'),'') else s.response_plan end,
    reminder_time=case when p_settings?'reminder_time' then (p_settings->>'reminder_time')::time else s.reminder_time end,
    updated_at=clock_timestamp()
  where s.user_id=uid returning * into saved;
  return to_jsonb(saved);
end;
$$;
revoke all on function public.save_private_settings(jsonb) from public, anon;
grant execute on function public.save_private_settings(jsonb) to authenticated;

-- A real server timestamp is a compare-and-swap version for journal edits.
-- Never let two updates share a timestamp, even inside the same transaction.
create or replace function private.touch_journal_entry_version()
returns trigger language plpgsql security invoker set search_path = ''
as $$
begin
  if new.id is distinct from old.id or new.user_id is distinct from old.user_id then
    raise exception using errcode='22023',message='L’identité de cette note ne peut pas être modifiée.';
  end if;
  new.updated_at := greatest(clock_timestamp(),old.updated_at+interval '1 microsecond');
  return new;
end;
$$;
revoke all on function private.touch_journal_entry_version() from public, anon, authenticated;
create or replace trigger journal_updated before update on public.journal_entries
for each row execute function private.touch_journal_entry_version();

-- Server search is literal (%, _ and backslashes are escaped); every request
-- is bounded to 21 records, not PostgREST's implicit row limit or an endless load.
create or replace function public.list_journal_entries(
  p_search text default '', p_offset integer default 0,
  p_limit integer default 21, p_motivation boolean default false
)
returns setof public.journal_entries language plpgsql stable security invoker set search_path = ''
as $$
declare uid uuid := auth.uid(); pattern text;
begin
  if uid is null or not private.sobrizen_health_consent_active() then
    raise exception using errcode='42501',message='Active le consentement au suivi pour ouvrir ton journal.';
  end if;
  if p_offset is null or p_offset<0 or p_limit is null or p_limit<1 or p_limit>21
    or p_search is null or char_length(p_search)>200 or p_motivation is null then
    raise exception using errcode='22023',message='Recherche ou page du journal invalide.';
  end if;
  pattern := '%'||replace(replace(replace(p_search,E'\\',E'\\\\'),'%',E'\\%'),'_',E'\\_')||'%';
  return query select j.* from public.journal_entries j
    where j.user_id=uid
      and ((j.kind='reflection' and j.title='Une pensée pour avancer · SobriZen')=p_motivation)
      and (j.title||' '||j.body) ilike pattern escape E'\\'
    order by j.entry_date desc,j.created_at desc,j.id desc
    limit p_limit offset p_offset;
end;
$$;
revoke all on function public.list_journal_entries(text,integer,integer,boolean) from public, anon;
grant execute on function public.list_journal_entries(text,integer,integer,boolean) to authenticated;

-- Explicit owner-initiated portability remains available after withdrawal.
-- No identity/table argument, no caller-controlled dynamic SQL, no write, no
-- community content from other users, no auth tokens, no billing/provider keys.
-- This returns image references/metadata, as the existing JSON export does;
-- binary image archives require the separate account-data request workflow.
create or replace function public.export_personal_data()
returns jsonb language plpgsql stable security definer set search_path = ''
as $$
declare uid uuid := auth.uid(); result jsonb; item record; rows jsonb;
begin
  if uid is null then raise exception using errcode='42501',message='Connecte-toi pour exporter tes données.'; end if;
  result := jsonb_build_object('version',5,'demo',false,'exported_at',statement_timestamp());
  for item in select * from (values
    ('profile','profiles','id',true),
    ('journey','sobriety_journeys','user_id',true),
    ('settings','user_settings','user_id',true),
    ('journey_timeline','journey_timelines','user_id',true),
    ('progress_settings','progress_settings','user_id',true),
    ('subscription_anchor','subscription_anchors','user_id',true),
    ('checks','daily_checkins','user_id',false),
    ('journal','journal_entries','user_id',false),
    ('urges','urge_events','user_id',false),
    ('reasons','reasons','user_id',false),
    ('program','program_progress','user_id',false),
    ('health_checkins','health_checkins','user_id',false),
    ('progress_chapters','progress_chapters','user_id',false),
    ('agenda_items','agenda_items','user_id',false),
    ('game_records','game_records','user_id',false),
    ('game_record_completions','game_record_completions','user_id',false)
  ) as allowlist(export_key,table_name,owner_column,single_row) loop
    -- The two other release migrations may be applied before or after this one.
    -- Once their tables exist they are automatically included in owner exports.
    if to_regclass(format('public.%I',item.table_name)) is null then
      rows := case when item.single_row then 'null'::jsonb else '[]'::jsonb end;
    else
      execute format('select coalesce(jsonb_agg(to_jsonb(t)),''[]''::jsonb) from public.%I t where t.%I=$1',item.table_name,item.owner_column)
        into rows using uid;
      if item.single_row then rows:=coalesce(rows->0,'null'::jsonb); end if;
    end if;
    result:=result||jsonb_build_object(item.export_key,rows);
  end loop;
  return result;
end;
$$;
revoke all on function public.export_personal_data() from public, anon;
grant execute on function public.export_personal_data() to authenticated;

-- Existing journey RPC definitions follow, unchanged except for an early
-- explicit consent guard. Their CAS/validation/locking behavior is preserved.

CREATE OR REPLACE FUNCTION public.save_journey_reference(p_started_on date, p_timezone text, p_baseline_units_week numeric, p_baseline_cost_week numeric, p_expected_journey_updated_at timestamp with time zone, p_expected_settings_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_started_at timestamptz;
  v_journey public.sobriety_journeys%rowtype;
  v_settings public.progress_settings%rowtype;
  v_has_settings boolean;
  v_note text;
begin
  if not private.sobrizen_health_consent_active() then
    raise exception using errcode='42501',message='Active le consentement au suivi pour enregistrer ton parcours.';
  end if;
  if v_uid is null then
    raise exception using errcode = '42501', message = 'Connecte-toi pour modifier ton point de départ.';
  end if;

  if p_timezone is null or not exists (
    select 1 from pg_catalog.pg_timezone_names as tz where tz.name = p_timezone
  ) then
    raise exception using errcode = '22023', message = 'Fuseau horaire invalide.';
  end if;

  if p_started_on is null or not pg_catalog.isfinite(p_started_on)
    or p_started_on < date '1900-01-01'
    or p_started_on > (pg_catalog.statement_timestamp() at time zone p_timezone)::date
  then
    raise exception using errcode = '22023', message = 'Choisis une date passée ou aujourd’hui, à partir de 1900.';
  end if;

  -- Accept zero, reject missing, out-of-range, nonfinite, and overprecise values.
  if p_baseline_units_week is null
    or not (p_baseline_units_week between 0 and 7000)
    or p_baseline_units_week <> pg_catalog.round(p_baseline_units_week, 2)
  then
    raise exception using errcode = '22023', message = 'Indique une consommation hebdomadaire entre 0 et 7 000, avec deux décimales au maximum.';
  end if;
  if p_baseline_cost_week is null
    or not (p_baseline_cost_week between 0 and 7000000)
    or p_baseline_cost_week <> pg_catalog.round(p_baseline_cost_week, 2)
  then
    raise exception using errcode = '22023', message = 'Indique une dépense hebdomadaire entre 0 et 7 000 000 €, avec deux décimales au maximum.';
  end if;

  -- Match the application's local-noon convention; never infer the date from UTC.
  v_started_at := (p_started_on + time '12:00:00') at time zone p_timezone;
  if (v_started_at at time zone p_timezone) <> (p_started_on + time '12:00:00') then
    raise exception using errcode = '22023', message = 'Cette date n’existe pas dans ce fuseau horaire.';
  end if;
  v_note := 'Estimation des habitudes avant le début déclaré du ' || pg_catalog.to_char(p_started_on, 'YYYY-MM-DD') || '.';

  -- Fixed lock order serializes this workflow and protects optimistic checks.
  select j.* into v_journey
  from public.sobriety_journeys as j
  where j.user_id = v_uid
  for update;
  if not found then
    raise exception using errcode = 'PT404', message = 'Ton parcours est introuvable. Actualise l’application.';
  end if;
  if p_expected_journey_updated_at is distinct from v_journey.updated_at then
    raise exception using errcode = 'PT409', message = 'Ton parcours a changé sur un autre écran. Actualise avant de réessayer.';
  end if;

  select s.* into v_settings
  from public.progress_settings as s
  where s.user_id = v_uid
  for update;
  v_has_settings := found;
  if (v_has_settings and p_expected_settings_updated_at is distinct from v_settings.updated_at)
    or (not v_has_settings and p_expected_settings_updated_at is not null)
  then
    raise exception using errcode = 'PT409', message = 'Tes repères ont changé sur un autre écran. Actualise avant de réessayer.';
  end if;

  update public.sobriety_journeys as j
  set started_at = v_started_at,
      weekly_spend_estimate = p_baseline_cost_week
  where j.user_id = v_uid
  returning j.* into v_journey;

  if v_has_settings then
    update public.progress_settings as s
    set baseline_units_week = p_baseline_units_week,
        baseline_cost_week = p_baseline_cost_week,
        baseline_note = v_note
    where s.user_id = v_uid
    returning s.* into v_settings;
  else
    begin
      insert into public.progress_settings (
        user_id, baseline_units_week, baseline_cost_week, baseline_note
      ) values (
        v_uid, p_baseline_units_week, p_baseline_cost_week, v_note
      )
      returning * into v_settings;
    exception when unique_violation then
      -- A concurrent settings insert cancels the journey update as well.
      raise exception using errcode = 'PT409', message = 'Tes repères ont changé sur un autre écran. Actualise avant de réessayer.';
    end;
  end if;

  return pg_catalog.jsonb_build_object(
    'journey', pg_catalog.to_jsonb(v_journey),
    'progress_settings', pg_catalog.to_jsonb(v_settings)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_journey_timeline(p_document jsonb, p_expected_revision integer, p_expected_journey_updated_at timestamp with time zone, p_expected_settings_updated_at timestamp with time zone, p_expected_chapter_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_journey public.sobriety_journeys%rowtype;
  v_settings public.progress_settings%rowtype;
  v_timeline public.journey_timelines%rowtype;
  v_chapter public.progress_chapters%rowtype;
  v_has_settings boolean;
  v_has_timeline boolean;
  v_goal jsonb;
  v_today date;
  v_started_at timestamptz;
  v_units numeric;
  v_cost numeric;
  v_weekly numeric;
  v_daily numeric;
  v_why text;
  v_note text;
  v_action text;
  v_support boolean;
  v_chapters jsonb;
begin
  if not private.sobrizen_health_consent_active() then
    raise exception using errcode='42501',message='Active le consentement au suivi pour enregistrer ton parcours.';
  end if;
  if v_uid is null then raise exception using errcode='42501',message='Connecte-toi pour enregistrer ton parcours.'; end if;
  if p_expected_revision is null or p_expected_revision < 0 or p_expected_revision=2147483647 then
    raise exception using errcode='22023',message='Version du parcours invalide.';
  end if;
  perform public.validate_journey_timeline_document(p_document);
  v_today := (pg_catalog.statement_timestamp() at time zone (p_document->>'timezone'))::date;
  v_goal := p_document->'goal';
  v_units := (p_document->'baseline'->>'units_week')::numeric;
  v_cost := (p_document->'baseline'->>'cost_week')::numeric;
  if p_document->'events'->-1->>'state'='abstinent'
    and p_document->'events'->-1->>'stopped_at' is not null then
    v_started_at := (p_document->'events'->-1->>'stopped_at')::timestamptz;
  else
    -- Compatibility mirror only: date-only history still has unknown clock precision.
    -- The canonical document, not this noon mirror, controls minute-resolution UI.
    v_started_at := (((p_document->'events' -> -1 ->> 'started_on')::date)+time '12:00:00') at time zone (p_document->>'timezone');
  end if;
  v_note := 'Estimation des habitudes à partir du ' || (p_document->'baseline'->>'started_on') || ', déclarée dans mon parcours.';
  v_why := nullif(v_goal->>'why','');
  v_action := nullif(v_goal->>'planned_action','');
  v_weekly := (v_goal->>'weekly_limit')::numeric;
  v_daily := (v_goal->>'daily_limit')::numeric;
  v_support := (v_goal->>'support_first')::boolean;

  -- Same lock order as save_journey_reference; no mutation before all CAS checks.
  select j.* into v_journey from public.sobriety_journeys j where j.user_id=v_uid for update;
  if not found then raise exception using errcode='PT404',message='Ton parcours est introuvable. Actualise l’application.'; end if;
  if p_expected_journey_updated_at is distinct from v_journey.updated_at then
    raise exception using errcode='PT409',message='Ton parcours a changé sur un autre écran. Actualise avant de réessayer.';
  end if;
  select s.* into v_settings from public.progress_settings s where s.user_id=v_uid for update;
  v_has_settings := found;
  if (v_has_settings and p_expected_settings_updated_at is distinct from v_settings.updated_at)
    or (not v_has_settings and p_expected_settings_updated_at is not null) then
    raise exception using errcode='PT409',message='Tes repères ont changé sur un autre écran. Actualise avant de réessayer.';
  end if;
  select t.* into v_timeline from public.journey_timelines t where t.user_id=v_uid for update;
  v_has_timeline := found;
  if (v_has_timeline and p_expected_revision <> v_timeline.revision)
    or (not v_has_timeline and p_expected_revision <> 0) then
    raise exception using errcode='PT409',message='Ton historique a changé sur un autre écran. Actualise avant de réessayer.';
  end if;
  select c.* into v_chapter from public.progress_chapters c where c.user_id=v_uid and c.effective_on<=v_today
    order by c.effective_on desc,c.created_at desc,c.id desc limit 1;
  if p_expected_chapter_id is distinct from v_chapter.id then
    raise exception using errcode='PT409',message='Ton cap a changé sur un autre écran. Actualise avant de réessayer.';
  end if;

  if v_journey.started_at is distinct from v_started_at
    or v_journey.weekly_spend_estimate is distinct from v_cost
    or v_journey.why_text is distinct from v_why then
    update public.sobriety_journeys j set started_at=v_started_at,weekly_spend_estimate=v_cost,why_text=v_why
      where j.user_id=v_uid returning j.* into v_journey;
  end if;
  if v_has_settings then
    if v_settings.baseline_units_week is distinct from v_units
      or v_settings.baseline_cost_week is distinct from v_cost
      or v_settings.baseline_note is distinct from v_note then
      update public.progress_settings s set baseline_units_week=v_units,baseline_cost_week=v_cost,baseline_note=v_note
        where s.user_id=v_uid returning s.* into v_settings;
    end if;
  else
    begin
      insert into public.progress_settings(user_id,baseline_units_week,baseline_cost_week,baseline_note)
        values(v_uid,v_units,v_cost,v_note) returning * into v_settings;
    exception when unique_violation then
      raise exception using errcode='PT409',message='Tes repères ont changé sur un autre écran. Actualise avant de réessayer.';
    end;
  end if;

  -- A drinking event or occasion never changes the chosen goal by itself.
  if v_chapter.id is null or v_chapter.mode is distinct from v_goal->>'mode'
    or v_chapter.weekly_limit is distinct from v_weekly or v_chapter.daily_limit is distinct from v_daily
    or v_chapter.support_first is distinct from v_support
    or nullif(v_chapter.planned_action,'') is distinct from v_action then
    insert into public.progress_chapters(user_id,effective_on,mode,weekly_limit,daily_limit,support_first,planned_action,origin,created_at)
      values(v_uid,v_today,v_goal->>'mode',v_weekly,v_daily,v_support,v_action,'chosen',pg_catalog.clock_timestamp());
  end if;

  if v_has_timeline then
    update public.journey_timelines t set document=p_document where t.user_id=v_uid and t.revision=p_expected_revision returning t.* into v_timeline;
    if not found then raise exception using errcode='PT409',message='Ton historique a changé. Actualise avant de réessayer.'; end if;
  else
    begin
      insert into public.journey_timelines(user_id,document) values(v_uid,p_document) returning * into v_timeline;
    exception when unique_violation then
      raise exception using errcode='PT409',message='Ton historique a changé sur un autre écran. Actualise avant de réessayer.';
    end;
  end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(c) order by c.effective_on,c.created_at,c.id),'[]'::jsonb)
    into v_chapters from public.progress_chapters c where c.user_id=v_uid;
  return pg_catalog.jsonb_build_object('journey',pg_catalog.to_jsonb(v_journey),'progress_settings',pg_catalog.to_jsonb(v_settings),'timeline',pg_catalog.to_jsonb(v_timeline),'chapters',v_chapters);
end;
$function$;

revoke all on function public.save_journey_reference(date,text,numeric,numeric,timestamptz,timestamptz) from public, anon;
grant execute on function public.save_journey_reference(date,text,numeric,numeric,timestamptz,timestamptz) to authenticated;
revoke all on function public.save_journey_timeline(jsonb,integer,timestamptz,timestamptz,uuid) from public, anon;
grant execute on function public.save_journey_timeline(jsonb,integer,timestamptz,timestamptz,uuid) to authenticated;

notify pgrst, 'reload schema';
commit;
